/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. Numbers that left
 * with a move are remembered in `project_issue_sequences` and are never
 * issued again in that project.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const sequence = getDb()
    .select({ highestNumber: projectIssueSequences.highestNumber })
    .from(projectIssueSequences)
    .where(
      and(
        eq(projectIssueSequences.orgId, orgId),
        eq(projectIssueSequences.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, sequence?.highestNumber ?? 0) + 1;
}

/** Records that `issued` has been used in the project, raising the high-water mark. */
export async function rememberIssuedNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issued: number,
): Promise<void> {
  const db = getDb();
  const existing = db
    .select({ highestNumber: projectIssueSequences.highestNumber })
    .from(projectIssueSequences)
    .where(
      and(
        eq(projectIssueSequences.orgId, orgId),
        eq(projectIssueSequences.projectId, projectId),
      ),
    )
    .get();

  if (!existing) {
    db.insert(projectIssueSequences)
      .values({ orgId, projectId, highestNumber: issued })
      .run();
    return;
  }

  if (existing.highestNumber < issued) {
    db.update(projectIssueSequences)
      .set({ highestNumber: issued })
      .where(
        and(
          eq(projectIssueSequences.orgId, orgId),
          eq(projectIssueSequences.projectId, projectId),
        ),
      )
      .run();
  }
}

