input.new_string:
/**
 * Leaves the issue's project and joins `toProjectId` in the same workspace.
 * Requires `issue:update` on the issue and `issue:create` in the target.
 * The target's per-project issue quota applies. A move onto the project the
 * issue already belongs to changes nothing and publishes nothing. The old
 * number is retired in the source project; the issue takes the target's next
 * number. Title, description, status, priority, assignee, estimate, due date,
 * labels, comments, attachments and links are left as they are.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const target = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", target.id, target);
  assertCan(actor, "issue:create", projectResource(target));

  if (before.projectId === target.id) {
    return before;
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, target.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${target.key}`,
    );
  }

  const fromNumber = before.number;
  const toNumber = await issueRepo.nextIssueNumber(input.orgId, target.id);
  await issueRepo.rememberIssuedNumber(
    input.orgId,
    before.projectId,
    fromNumber,
  );
  const after = await issueRepo.assignIssueToProject(
    input.orgId,
    before.id,
    target.id,
    toNumber,
  );
  await issueRepo.rememberIssuedNumber(input.orgId, target.id, toNumber);

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId: before.projectId,
    toProjectId: target.id,
    fromNumber,
    toNumber,
  });

  return after;
}

